ALTER TABLE "station_layout_items" ADD CONSTRAINT "station_layout_items_kind_check" CHECK (("station_layout_items"."kind" = 'equipment' and "station_layout_items"."equipment_id" is not null and "station_layout_items"."configuration_id" is not null and "station_layout_items"."length_cm" is null and "station_layout_items"."text" is null) or ("station_layout_items"."kind" = 'arrow' and "station_layout_items"."equipment_id" is null and "station_layout_items"."configuration_id" is null and "station_layout_items"."length_cm" between 10 and 5000 and "station_layout_items"."text" is null) or ("station_layout_items"."kind" = 'text' and "station_layout_items"."equipment_id" is null and "station_layout_items"."configuration_id" is null and "station_layout_items"."length_cm" is null and length("station_layout_items"."text") between 1 and 200));--> statement-breakpoint
ALTER TABLE "station_layout_items" ADD CONSTRAINT "station_layout_items_position_check" CHECK ("station_layout_items"."x_cm" between -2500 and 2500 and "station_layout_items"."y_cm" between -2500 and 2500);